def count_nums(arr):
    def sum_of_digits(n):
        total = 0
        negative = n < 0
        n = abs(n)
        while n > 0:
            digit = n % 10
            if negative and total == 0:
                digit = -digit
                negative = False
            total += digit
            n //= 10
        return total

    count = 0
    for num in arr:
        if sum_of_digits(num) > 0:
            count += 1
    return count
